import 'paper_doll_layers.g.dart';

/// Composes flat paper-doll layers and applies automatic pixel-art shading.
///
/// Layers come from `paper_doll_layers.g.dart` (generated by
/// `tool/art/paper_doll_gen.py`). Each layer holds FLAT material tokens; this
/// class stacks them (later layers on top) and turns every pixel into one
/// shaded output token, following the same rules as `tool/art/preview.py`:
///
/// 1. Pixels touching transparency become the dark silhouette outline.
/// 2. Hand-placed tokens keep their tone (lowercase = shadow, digit = glint).
/// 3. A pixel whose right/bottom neighbour is a different region (other
///    material, or same material from another layer) becomes the deep tone
///    -> inner lines that separate parts (hood vs robe, helm vs tunic...).
/// 4. Otherwise light comes from the top-left: highlight on top/left edges,
///    shadow on bottom/right edges, base elsewhere.
///
/// Output tokens are fixed per (material, tone) so the colour palette depends
/// only on the hero's appearance (see [PaperDollTokens]).
abstract final class PaperDollShader {
  static const int width = paperDollWidth;
  static const int height = paperDollHeight;

  static final Map<String, List<String>> _decoded = {};
  static final Map<String, List<String>> _cache = {};

  /// Stacks [layerKeys] (bottom to top) and returns shaded output rows.
  /// Unknown or empty keys are ignored. Results are cached per key list.
  static List<String> compose(List<String> layerKeys) {
    final cacheKey = layerKeys.join('|');
    final cached = _cache[cacheKey];
    if (cached != null) return cached;

    final tokens = List<int>.filled(width * height, _transparent);
    final owners = List<int>.filled(width * height, -1);
    for (var li = 0; li < layerKeys.length; li++) {
      final rows = layerRows(layerKeys[li]);
      for (var y = 0; y < rows.length && y < height; y++) {
        final row = rows[y];
        for (var x = 0; x < row.length && x < width; x++) {
          final c = row.codeUnitAt(x);
          if (c == _transparent) continue;
          tokens[y * width + x] = c;
          owners[y * width + x] = li;
        }
      }
    }
    final out = _shade(tokens, owners);
    if (_cache.length > 256) _cache.clear(); // simple bound for long sessions
    return _cache[cacheKey] = out;
  }

  /// Decoded (run-length expanded) rows of one layer; empty if unknown.
  static List<String> layerRows(String key) {
    final hit = _decoded[key];
    if (hit != null) return hit;
    final encoded = paperDollLayers[key];
    if (encoded == null || encoded.isEmpty) return _decoded[key] = const [];
    return _decoded[key] = [for (final r in encoded) _expand(r)];
  }

  /// Whether a layer key exists in the generated catalog.
  static bool hasLayer(String key) => paperDollLayers.containsKey(key);

  /// Symbols used in the generated file for the digit tokens 1..0.
  static const String _digitEscapes = r'!@#$%^&*()';

  static String _expand(String rle) {
    final b = StringBuffer();
    var count = 0;
    for (final ch in rle.split('')) {
      final digit = int.tryParse(ch);
      if (digit != null) {
        count = count * 10 + digit;
        continue;
      }
      final esc = _digitEscapes.indexOf(ch);
      final token = esc >= 0 ? '1234567890'[esc] : ch;
      b.write(token * (count == 0 ? 1 : count));
      count = 0;
    }
    return b.toString();
  }

  // --- token classification ------------------------------------------------
  static const int _transparent = 0x2E; // '.'
  static const String _regions = 'SHTLPCMAGR';
  static const String _forcedShadow = 'shtlpcmagr';
  static const String _forcedHighlight = '1234567890';

  /// Material index 0..9 for region/forced tokens, -1 for fixed/none.
  static int _material(int c) {
    if (c == _transparent) return -2;
    final ch = String.fromCharCode(c);
    var i = _regions.indexOf(ch);
    if (i >= 0) return i;
    i = _forcedShadow.indexOf(ch);
    if (i >= 0) return i;
    i = _forcedHighlight.indexOf(ch);
    if (i >= 0) return i;
    return -1; // K, W, E
  }

  static bool _isRegion(int c) => _regions.contains(String.fromCharCode(c));

  static List<String> _shade(List<int> tokens, List<int> owners) {
    int tok(int x, int y) =>
        (x < 0 || y < 0 || x >= width || y >= height) ? _transparent : tokens[y * width + x];
    int mat(int x, int y) => _material(tok(x, y));

    final rows = <String>[];
    for (var y = 0; y < height; y++) {
      final b = StringBuffer();
      for (var x = 0; x < width; x++) {
        final t = tok(x, y);
        if (t == _transparent) {
          b.write('.');
          continue;
        }
        final ch = String.fromCharCode(t);
        if (ch == 'K' || ch == 'W' || ch == 'E') {
          b.write(ch);
          continue;
        }
        final m = _material(t);
        // 1. silhouette outline
        if (tok(x + 1, y) == _transparent ||
            tok(x - 1, y) == _transparent ||
            tok(x, y + 1) == _transparent ||
            tok(x, y - 1) == _transparent) {
          b.write('K');
          continue;
        }
        // 2. hand-placed tones
        if (_forcedShadow.contains(ch)) {
          b.write(PaperDollTokens.tone(m, PaperDollTone.shadow));
          continue;
        }
        if (_forcedHighlight.contains(ch)) {
          b.write(PaperDollTokens.tone(m, PaperDollTone.highlight));
          continue;
        }
        // 3. inner borders (different material, or same material from another layer)
        final own = owners[y * width + x];
        var inner = false;
        for (final (nx, ny) in [(x + 1, y), (x, y + 1)]) {
          if (nx >= width || ny >= height) continue;
          final n = tok(nx, ny);
          if (_isRegion(n) && (_material(n) != m || owners[ny * width + nx] != own)) {
            inner = true;
            break;
          }
        }
        if (inner) {
          b.write(PaperDollTokens.tone(m, PaperDollTone.deep));
          continue;
        }
        // 4. light from the top-left
        final tl = mat(x - 1, y) != m || mat(x, y - 1) != m;
        final br = mat(x + 1, y) != m || mat(x, y + 1) != m;
        final tone = (tl && !br)
            ? PaperDollTone.highlight
            : br
                ? PaperDollTone.shadow
                : PaperDollTone.base;
        b.write(PaperDollTokens.tone(m, tone));
      }
      rows.add(b.toString());
    }
    return rows;
  }
}

/// Tones produced by the shader for every material.
enum PaperDollTone { highlight, base, shadow, deep }

/// Paper-doll materials, in token order (`S H T L P C M A G R`).
enum PaperDollMaterial { skin, hair, torso, leather, pants, cape, steel, gold, aura, crimson }

/// Fixed output alphabet: one character per (material, tone), plus
/// `K` outline, `W` white and `E` eye iris.
abstract final class PaperDollTokens {
  static const String _alphabet = 'abcdefghijklmnopqrstuvwxyzABCDFGHIJLMNOQ';

  static String tone(int material, PaperDollTone tone) =>
      _alphabet[material * 4 + tone.index];

  static String of(PaperDollMaterial m, PaperDollTone t) => tone(m.index, t);
}
